DOWNGRD_12 = bytes.fromhex("444f574e47524401")   # "DOWNGRD" + 0x01
DOWNGRD_11 = bytes.fromhex("444f574e47524400")   # "DOWNGRD" + 0x00

def check_server_random(server_random: bytes, negotiated: str) -> None:
    """What a TLS 1.3-capable client does when a server picks an older version."""
    if negotiated != "TLSv1.3" and server_random[-8:] in (DOWNGRD_12, DOWNGRD_11):
        raise ConnectionError("illegal_parameter: server supports TLS 1.3, "
                              "someone forced a downgrade")

