def name_matches(pattern: str, host: str) -> bool:
    p = pattern.lower().split(".")
    h = host.lower().split(".")
    if len(p) != len(h):
        return False               # wildcard covers one label only
    if p[0] == "*":
        if "*" in ".".join(p[1:]):
            return False           # only one wildcard, leftmost
        return p[1:] == h[1:]      # rest must match exactly
    return p == h

